-- =====================================================================
-- 009 — Mapa: piscinas de la camaronera (capa "Piscinas")
-- =====================================================================
--
-- Qué agrega
--   piscinas   Cada piscina como un polígono sobre el mapa, con su nombre
--              (el del plano: L01, K20, PCM04…), su sector (la letra) y las
--              hectáreas rotuladas en el plano. La capa "Piscinas" del mapa
--              las dibuja; al hacer clic se ven el nombre, el área rotulada y
--              la del dibujo. El administrador corrige la forma con el editor
--              de vértices de la app (y los datos con «Editar datos»).
--                puntos   [[lat, lng], …]: el contorno, de 3 a 2000 puntos
--                         (sin repetir el primero al final).
--                fuente   de dónde salió el dibujo: vector (trazos del PDF,
--                         exacto), imagen (segmentación del plano),
--                         aproximada o manual.
--                revisar  true si conviene mirarla (p. ej. sin hectáreas
--                         rotuladas).
--
-- Semilla: las 127 piscinas del plano de lotes de agosto de 2026 (Consultora
-- ZH), georreferenciado como la capa "Plano" (error esperable: 5 a 10 m). Se
-- generaron con kit-continuar/plano/piscinas.py.
--
-- Permisos: las lee quien tiene "ver_mapa"; las escribe solo el
-- administrador. GRANT explícito, como en la 002/003/006/007. Los cambios
-- quedan en auditoría (registrar_auditoria()).
--
-- Si esta migración no se corre, la app sigue igual, sin la capa Piscinas.
--
-- Cómo correrla: pegar TODO el archivo en el SQL Editor de Supabase y
-- ejecutar. Va en una sola transacción: si algo falla, no queda nada a medias.
-- =====================================================================

BEGIN;

DO $$
BEGIN
  IF to_regclass('public.ubicaciones') IS NULL THEN
    RAISE EXCEPTION 'Falta la migración 002 (public.ubicaciones no existe).';
  END IF;
  IF to_regclass('public.piscinas') IS NOT NULL THEN
    RAISE EXCEPTION 'La migración 009 ya fue aplicada (public.piscinas existe).';
  END IF;
  IF to_regprocedure('public.registrar_auditoria()') IS NULL OR to_regprocedure('public.puede(text)') IS NULL OR to_regprocedure('public.es_admin()') IS NULL THEN
    RAISE EXCEPTION 'Faltan funciones base (registrar_auditoria, puede, es_admin).';
  END IF;
END $$;

-- ---------------------------------------------------------------------
-- 1. Validación del contorno (la usa el CHECK). Mismas reglas que
--    validarPuntosPiscina() en nucleo/piscinas.js.
-- ---------------------------------------------------------------------

CREATE FUNCTION public.f_piscinas_puntos_validos(p jsonb)
RETURNS boolean
LANGUAGE sql
IMMUTABLE
SET search_path = ''
AS $$
  SELECT CASE
    WHEN p IS NULL OR jsonb_typeof(p) <> 'array' THEN false
    WHEN jsonb_array_length(p) NOT BETWEEN 3 AND 2000 THEN false
    WHEN NOT (SELECT bool_and(coalesce(
                jsonb_typeof(q) = 'array'
                AND jsonb_array_length(q) = 2
                AND jsonb_typeof(q -> 0) = 'number'
                AND jsonb_typeof(q -> 1) = 'number', false))
              FROM jsonb_array_elements(p) AS q) THEN false
    ELSE (SELECT bool_and((q ->> 0)::float8 BETWEEN -90 AND 90 AND (q ->> 1)::float8 BETWEEN -180 AND 180)
            FROM jsonb_array_elements(p) AS q)
  END
$$;
COMMENT ON FUNCTION public.f_piscinas_puntos_validos(jsonb) IS 'true si p = [[lat, lng], …] con 3 a 2000 puntos y coordenadas en rango.';

-- ---------------------------------------------------------------------
-- 2. Tabla
-- ---------------------------------------------------------------------

CREATE TABLE public.piscinas (
  id              bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  nombre          text NOT NULL CONSTRAINT piscinas_nombre_valido CHECK (btrim(nombre) <> '' AND char_length(nombre) <= 40),
  sector          text CONSTRAINT piscinas_sector_valido CHECK (sector IS NULL OR (btrim(sector) <> '' AND char_length(sector) <= 40)),
  hectareas       numeric(8,2) CONSTRAINT piscinas_hectareas_validas CHECK (hectareas IS NULL OR hectareas > 0),
  puntos          jsonb NOT NULL CONSTRAINT piscinas_geom_valida CHECK (public.f_piscinas_puntos_validos(puntos)),
  fuente          text NOT NULL DEFAULT 'manual' CONSTRAINT piscinas_fuente_valida CHECK (fuente IN ('vector', 'imagen', 'aproximada', 'manual')),
  revisar         boolean NOT NULL DEFAULT false,
  notas           text CONSTRAINT piscinas_notas_largo CHECK (notas IS NULL OR char_length(notas) <= 1000),
  orden           integer NOT NULL DEFAULT 0,
  activa          boolean NOT NULL DEFAULT true,
  creado_en       timestamptz NOT NULL DEFAULT now(),
  creado_por      uuid DEFAULT auth.uid(),
  actualizado_en  timestamptz NOT NULL DEFAULT now(),
  actualizado_por uuid DEFAULT auth.uid()
);
COMMENT ON TABLE public.piscinas IS 'Piscinas de la camaronera como polígonos [[lat,lng],…] para la capa "Piscinas" del mapa, con el nombre y las hectáreas del plano.';
CREATE UNIQUE INDEX piscinas_nombre_unico ON public.piscinas (lower(btrim(nombre)));

-- Quién y cuándo la tocó por última vez.
CREATE FUNCTION public.f_piscinas_actualizada()
RETURNS trigger
LANGUAGE plpgsql
SET search_path = ''
AS $$
BEGIN
  NEW.actualizado_en := now();
  NEW.actualizado_por := auth.uid();
  RETURN NEW;
END $$;
CREATE TRIGGER trg_piscinas_actualizada BEFORE UPDATE ON public.piscinas FOR EACH ROW EXECUTE FUNCTION public.f_piscinas_actualizada();
CREATE TRIGGER audit_piscinas AFTER INSERT OR DELETE OR UPDATE ON public.piscinas FOR EACH ROW EXECUTE FUNCTION public.registrar_auditoria();

-- ---------------------------------------------------------------------
-- 3. RLS (sel_/ins_/upd_/del_<tabla>, como el resto)
-- ---------------------------------------------------------------------

ALTER TABLE public.piscinas ENABLE ROW LEVEL SECURITY;
CREATE POLICY sel_piscinas ON public.piscinas FOR SELECT USING (public.puede('ver_mapa'));
CREATE POLICY ins_piscinas ON public.piscinas FOR INSERT WITH CHECK (public.es_admin());
CREATE POLICY upd_piscinas ON public.piscinas FOR UPDATE USING (public.es_admin()) WITH CHECK (public.es_admin());
CREATE POLICY del_piscinas ON public.piscinas FOR DELETE USING (public.es_admin());

-- ---------------------------------------------------------------------
-- 4. GRANT explícito. id es IDENTITY: no hace falta GRANT sobre la secuencia.
-- ---------------------------------------------------------------------

GRANT SELECT, INSERT, UPDATE, DELETE ON TABLE public.piscinas TO anon, authenticated;
REVOKE ALL ON FUNCTION public.f_piscinas_puntos_validos(jsonb) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.f_piscinas_puntos_validos(jsonb) TO anon, authenticated;
REVOKE ALL ON FUNCTION public.f_piscinas_actualizada() FROM PUBLIC;

-- ---------------------------------------------------------------------
-- 5. Semilla: las piscinas del plano de lotes (agosto de 2026)
-- ---------------------------------------------------------------------


COMMIT;
